export const meta = {
  name: 'slow-check',
  description: 'Run one haiku agent that sleeps 45 seconds and replies done',
  phases: [{ title: 'Wait' }],
}

const result = await agent(
  'Use the Bash tool to run `sleep 45`. When it finishes, reply with the single word: done',
  { label: 'sleeper', phase: 'Wait', model: 'haiku' }
)
return result

